 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Rectangular frames encode their fill color by their side length.
    fill_by_side = {5: 8, 7: 4, 9: 3}
    seen = set()
    frames = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = set()
            while stack:
                y, x = stack.pop()
                comp.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            r0 = min(y for y, x in comp)
            r1 = max(y for y, x in comp)
            c0 = min(x for y, x in comp)
            c1 = max(x for y, x in comp)
            side_h, side_w = r1 - r0 + 1, c1 - c0 + 1
            if side_h != side_w or side_h not in fill_by_side:
                continue
            border = {(y, x) for y in range(r0, r1 + 1) for x in range(c0, c1 + 1)
                      if y in (r0, r1) or x in (c0, c1)}
            if comp == border:
                frames.append((r0, r1, c0, c1, fill_by_side[side_h]))
    out = [row[:] for row in grid]
    for r0, r1, c0, c1, color in frames:
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                if out[r][c] == 0:
                    out[r][c] = color
    return out
